#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn min_max_ints() {
        assert_eq!(min_max(&[3, 9, -2, 7]), Some((-2, 9)));
        assert_eq!(min_max(&[5]), Some((5, 5)));
        assert_eq!(min_max::<i32>(&[]), None);
    }

    #[test]
    fn min_max_other_types() {
        assert_eq!(min_max(&[2.5, -1.0, 8.25]), Some((-1.0, 8.25)));
        assert_eq!(min_max(&['q', 'a', 'z']), Some(('a', 'z')));
        assert_eq!(min_max(&["pear", "apple", "zoo"]), Some(("apple", "zoo")));
    }

    #[test]
    fn dedup_ints() {
        assert_eq!(dedup_consecutive(&[1, 1, 2, 2, 2, 1, 3, 3]), vec![1, 2, 1, 3]);
        assert_eq!(dedup_consecutive::<i32>(&[]), Vec::<i32>::new());
    }

    #[test]
    fn dedup_strings() {
        let v = vec!["a".to_string(), "a".to_string(), "b".to_string()];
        assert_eq!(dedup_consecutive(&v), vec!["a".to_string(), "b".to_string()]);
    }
}
